package com.eventhub.controller;import com.eventhub.dto.*;import com.eventhub.service.RegistrationService;import lombok.RequiredArgsConstructor;import org.springframework.data.domain.Page;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api") @RequiredArgsConstructor public class RegistrationController{private final RegistrationService service;@PostMapping("/events/{id}/register") @PreAuthorize("hasRole('STUDENT')") public ResponseEntity<RegistrationResponse> register(org.springframework.security.core.Authentication a,@PathVariable Long id){return ResponseEntity.status(HttpStatus.CREATED).body(service.register(a.getName(),id));}@DeleteMapping("/events/{id}/register") @PreAuthorize("hasRole('STUDENT')") public ResponseEntity<RegistrationResponse> cancel(org.springframework.security.core.Authentication a,@PathVariable Long id){return ResponseEntity.ok(service.cancel(a.getName(),id));}@GetMapping("/users/me/registrations") @PreAuthorize("isAuthenticated()") public ResponseEntity<Page<RegistrationResponse>> mine(org.springframework.security.core.Authentication a,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="10")int size){return ResponseEntity.ok(service.mine(a.getName(),page,size));}@PostMapping("/events/{id}/waitlist") @PreAuthorize("hasRole('STUDENT')") public ResponseEntity<WaitlistResponse> waitlist(org.springframework.security.core.Authentication a,@PathVariable Long id){return ResponseEntity.status(HttpStatus.CREATED).body(service.joinWaitlist(a.getName(),id));}@DeleteMapping("/events/{id}/waitlist") @PreAuthorize("hasRole('STUDENT')") public ResponseEntity<WaitlistResponse> cancelWaitlist(org.springframework.security.core.Authentication a,@PathVariable Long id){return ResponseEntity.ok(service.cancelWaitlist(a.getName(),id));}@GetMapping("/events/{id}/waitlist") @PreAuthorize("hasAnyRole('ORGANIZER','ADMIN','SUPER_ADMIN')") public ResponseEntity<Page<WaitlistResponse>> eventWaitlist(org.springframework.security.core.Authentication a,@PathVariable Long id,@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="20")int size){return ResponseEntity.ok(service.eventWaitlist(a.getName(),id,page,size));}}
